import { screens } from './data.js';
export const S={deployment:{demo:false,maxUploadBytes:null},user:null,projects:[],archive:[],news:[],pages:[],questions:[],evaluations:[],config:{criteria:[]},mentors:[],consents:[],messages:[],users:[],mailings:[],attempt:null};
export const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={arrow:'M5 12h14m-6-6 6 6-6 6',download:'M12 3v12m-5-5 5 5 5-5M4 16v4h16v-4',user:'M20 21v-2a7 7 0 0 0-14 0v2M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8',users:'M17 21v-2a6 6 0 0 0-12 0v2M11 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8M18 4a4 4 0 0 1 0 8m1 3a6 6 0 0 1 3 5',home:'m3 10 9-7 9 7v11h-6v-7H9v7H3Z',file:'M14 2H5v20h14V7Zm0 0v5h5M8 12h8m-8 4h6',book:'M12 5c-3-3-6-3-10-2v16c4-1 7-1 10 2 3-3 6-3 10-2V3c-4-1-7-1-10 2Zm0 0v16',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 2h6l1 3 3 1 3 3v6l-3 1-1 3-3 3H9l-1-3-3-1-3-3V9l3-1 1-3Z',mail:'M3 4h18v16H3Zm0 2 9 7 9-7',search:'M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14m5-2 6 6',check:'m4 12 5 5L20 6',clock:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20m0-16v6l4 2',leaf:'M3 20C1 7 8 3 21 3c0 13-4 20-15 16M3 21 16 8',globe:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20M2 12h20M12 2c-7 8-7 12 0 20 7-8 7-12 0-20',trophy:'M7 3h10v8a5 5 0 0 1-10 0Zm0 2H3v4a4 4 0 0 0 4 4m10-8h4v4a4 4 0 0 1-4 4M12 16v5m-5 0h10',video:'M2 5h14v14H2Zm14 5 6-4v12l-6-4',lock:'M5 10h14v12H5Zm3 0V6a4 4 0 0 1 8 0v4m-4 5v3',eye:'M2 12c5-9 15-9 20 0-5 9-15 9-20 0Zm10 3a3 3 0 1 0 0-6 3 3 0 0 0 0 6',edit:'m3 17 14-14 4 4-14 14H3Zm11-11 4 4',grid:'M3 3h7v7H3Zm11 0h7v7h-7ZM3 14h7v7H3Zm11 0h7v7h-7Z',chart:'M3 3v18h18M7 16v-5m5 5V7m5 9V4',link:'m10 7 3-3a5 5 0 0 1 7 7l-3 3M14 17l-3 3a5 5 0 0 1-7-7l3-3m1 6 8-8',calendar:'M3 5h18v17H3Zm4-3v6m10-6v6M3 11h18',pin:'M12 22s8-8 8-14a8 8 0 0 0-16 0c0 6 8 14 8 14Zm0-11a3 3 0 1 0 0-6 3 3 0 0 0 0 6',phone:'M5 3h4l2 5-3 2c1 3 3 5 6 6l2-3 5 2v4c-9 4-21-8-16-16',heart:'M12 21 3 12C-3 3 7-2 12 6c5-8 15-3 9 6Z',cap:'m2 7 10-5 10 5-10 5Zm4 3v8c4 3 8 3 12 0v-8m4-3v9',logout:'M9 4H3v16h6m-1-8h13m-5-5 5 5-5 5',upload:'M12 17V3m-5 5 5-5 5 5M3 16v6h18v-6'};
export const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
export const link=(id,label,cls='')=>`<a href="#/${id}" class="${cls}">${label}</a>`;
export const button=(label,action,cls='',attrs='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
export const badge=(label)=>`<span class="badge ${/провер|ожида|модера|черновик/i.test(label)?'orange':/работ|готовит/i.test(label)?'blue':/отклон|блокир/i.test(label)?'red':''}">${esc(label)}</span>`;
export const photo=(name,alt='',cls='')=>`<img class="${cls}" src="assets/${name}.webp" alt="${esc(alt)}" loading="lazy">`;
export const brand=()=>link('home',`<img src="assets/logo.png" alt=""> <span>АРКТИКА</span>`,'brand');
export const name=()=>S.user?.profile.name||'Анна Петрова';
export const header=(page,overlay=false)=>`<header class="topbar ${overlay?'over-image':''}">${brand()}<nav class="topnav" aria-label="Основная навигация"><div class="nav-group">${link('about','О КОНКУРСЕ', ['about','history','rules'].includes(page)?'active':'')}<div class="dropdown">${link('about','О конкурсе')}${link('history','История конкурса')}${link('rules','Положение и FAQ')}${link('partners','Партнёрам')}${link('contacts','Контакты')}</div></div><div class="nav-group">${link('participate','УЧАСТНИКАМ',['participate','documents'].includes(page)?'active':'')}<div class="dropdown">${link('participate','Как участвовать')}${link('documents','Шаблоны документов')}${link('archive','Архив проектов')}${link('test-intro','Проверить знания')}${link('submit','Подать проект')}</div></div><div class="nav-group">${link('explore','ИССЛЕДУЙ АРКТИКУ',['explore','bear','media'].includes(page)?'active':'')}<div class="dropdown">${link('explore','Темы для исследования')}${link('bear','Белый медведь')}${link('media','Медиатека')}</div></div>${link('news','НОВОСТИ',page.startsWith('news')?'active':'')}</nav>${link(S.user?roleHome(S.user.role):'login',S.user?esc(name().split(' ').slice(0,2).join(' '))+' ⌄':'Личный кабинет ↗','btn') }<button class="menu-toggle" aria-label="Открыть меню" aria-expanded="false" data-action="menu">☰</button></header>`;
export const footer=()=>`<footer class="footer">${brand()}<nav class="footer-links">${link('about','О КОНКУРСЕ')}${link('participate','УЧАСТНИКАМ')}${link('explore','ИССЛЕДУЙ АРКТИКУ')}${link('news','НОВОСТИ')}</nav><div class="footer-social">${link('contacts','ᴠκ')}${link('contacts','➤')}${link('media','▶')}</div>${link('contacts','Связаться с нами','footer-end')}</footer>`;
export const banner=(title,desc='',{tall=false,landscape=true,crumb=true,eyebrow=''}={})=>`<section class="hero-banner hero-scene ${landscape?'banner-landscape':''} ${tall?'tall':''}">${crumb?`<div class="breadcrumbs">${link('home','Главная')} / <span>${esc(title)}</span></div>`:''}${eyebrow?`<div class="eyebrow">${esc(eyebrow)}</div>`:''}<h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</section>`;
export const tabs=(labels,active=0,key='tab')=>`<div class="tabs" data-tabs="${key}">${labels.map((l,i)=>`<button type="button" class="tab ${i===active?'active':''}" data-tab="${i}" data-key="${key}">${esc(l)}</button>`).join('')}</div>`;
let fieldSequence=0;
export const field=(label,key,value='',type='text',extra='')=>{const unique='field-'+(++fieldSequence)+'-'+key;return '<div class="field"><label for="'+unique+'">'+label+'</label>'+(type==='textarea'?'<textarea id="'+unique+'" name="'+key+'" '+extra+'>'+esc(value)+'</textarea>':type==='password'?'<div class="password-wrap"><input id="'+unique+'" name="'+key+'" type="password" value="'+esc(value)+'" '+extra+'><button type="button" class="password-eye" data-action="password" data-target="'+unique+'" aria-label="Показать пароль">'+icon('eye')+'</button></div>':'<input id="'+unique+'" name="'+key+'" type="'+type+'" value="'+esc(value)+'" '+extra+'>')+'</div>';};
export const select=(label,key,options,value='')=>{const unique='select-'+(++fieldSequence)+'-'+key;return '<div class="field"><label for="'+unique+'">'+label+'</label><select name="'+key+'" id="'+unique+'">'+options.map(o=>'<option '+(String(o)===String(value)?'selected':'')+'>'+esc(o)+'</option>').join('')+'</select></div>';};
export const search=(placeholder='Поиск…')=>`<div class="search">${icon('search')}<input class="control" type="search" data-search placeholder="${esc(placeholder)}" aria-label="${esc(placeholder)}"></div>`;
export const filters=(options=[])=>`<div class="filters">${options.map((opts,i)=>`<select class="control" data-filter="${i}" aria-label="${esc(opts[0])}">${opts.map(v=>`<option>${esc(v)}</option>`).join('')}</select>`).join('')}${search()}</div>`;
export const heading=(title,desc='',actions='')=>`<div class="page-heading"><div><h1>${esc(title)}</h1>${desc?`<p>${esc(desc)}</p>`:''}</div>${actions}</div>`;
export const empty=(msg)=>`<div class="empty-state"><h3>${esc(msg)}</h3><p>Здесь появятся данные, когда ты сделаешь следующий шаг.</p></div>`;
export const roleHome=role=>({participant:'dashboard',teacher:'teacher',expert:'expert',commission:'ranking',admin:'admin'}[role]||'dashboard');
export const roles={participant:'Участник',teacher:'Педагог',expert:'Эксперт',commission:'Комиссия',admin:'Администратор'};
const participantNav=[['dashboard','Обзор','home'],['profile','Мой профиль','user'],['mentor','Мой руководитель','users'],['project','Мои проекты','file'],['test-intro','Тестовые задания','book'],['achievements','Мои достижения','trophy'],['documents','Материалы','book'],['security','Настройки','settings']];
const projectNav=[['project','Мой проект','file'],['project-results','Результаты','chart'],['defense','ВКС-защита','video'],['profile','Мой профиль','user']];
const adminNav=[['admin','Обзор','home'],['users','Участники','users'],['distribution','Проекты','file'],['content','Контент','book'],['settings','Конкурс','settings'],['questions','Банк вопросов','book'],['mailing','Рассылки','mail'],['analytics','Отчёты','chart']];
const specialistNav={teacher:[['teacher','Мои ученики','users'],['teacher?view=invitations','Приглашения','mail'],['teacher?view=certificate','Сертификаты','trophy'],['documents','Материалы','book']],expert:[['expert','Мои задания','users'],['evaluation','Оценка проекта','file'],['documents','Материалы','book']],commission:[['ranking','Комиссия / Рейтинг','users'],['archive','Проекты','file'],['documents','Материалы','book']]};
export const workspace=(page,title,content,role='participant')=>{const isProject=['project','project-results','defense'].includes(page);const nav=role==='admin'?adminNav:role==='participant'?(isProject?projectNav:participantNav):specialistNav[role];return `<div class="workspace"><aside class="sidebar">${brand()}<nav aria-label="Кабинет">${(nav||participantNav).map(([id,label,i])=>link(id,icon(i)+esc(label),page===id?'active':'')).join('')}</nav><div class="sidebar-quote ${role!=='participant'?'upper':''}">Знания сегодня —<br>для сохранения<br>Арктики завтра.</div>${link('home','К конкурсу ↗','sidebar-exit')}</aside><div class="workspace-main"><header class="workspace-bar ${role!=='participant'||isProject?'dark':''}"><strong>${esc(title)}</strong><button class="account" data-action="account"><span class="avatar">${esc(name().split(' ').map(s=>s[0]).slice(0,2).join(''))}</span><span>${esc(name().split(' ').slice(0,2).join(' '))}<small>${roles[S.user?.role]||roles[role]}</small></span>⌄</button></header><main id="main" class="workspace-content ${role==='admin'?'admin-content':''}">${content}</main></div></div>`;};
export const publicPage=(id,body)=>`${header(id)}<main id="main" class="fade-in" data-page="${id}">${body}</main>${footer()}`;
export const fileLink=(kind,label='Скачать PDF')=>`<a class="btn sm" href="/api/document?kind=${kind}" target="_blank">${icon('download')}${label}</a>`;
export const table=(heads,rows)=>`<div class="table-wrap"><table class="data-table"><thead><tr>${heads.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
export const row=(cells,attr='')=>`<tr ${attr}>${cells.map(c=>`<td>${c}</td>`).join('')}</tr>`;
export const cardTitle=(title,actions='',i='')=>`<div class="card-title"><h3>${i?icon(i):''}${title}</h3>${actions}</div>`;
export const projectCell=p=>`<div class="project-cell">${photo(p.image||'iceberg')}<div><strong>${esc(p.name)}</strong><small>${esc(p.author||'')}</small></div></div>`;
export const metrics=items=>`<div class="metric-grid">${items.map(([n,l,i])=>`<div class="metric ${i?'icon-metric':''}">${i?icon(i):''}<div><strong>${esc(n)}</strong><p>${esc(l)}</p></div></div>`).join('')}</div>`;
export const date=d=>new Date(d||Date.now()).toLocaleDateString('ru-RU');
export function screenMap(){return `<h2>Все экраны</h2><div class="screen-map">${screens.map(s=>`${s.number%4===1?`<div class="group-label">${esc(s.group)}</div>`:''}${link(s.id,`<span>${String(s.number).padStart(2,'0')}</span>${esc(s.title)}`)}`).join('')}</div>`;}
